window.FOUNDRY_COMPONENTS.push(
  { group: 'Components', id: 'audio', name: 'Audio', description: 'Accessible native audio playback with a real bundled spoken-word MP3, source URL testing, local file insertion, transcript, metadata, and fallback content.', preview: `<div class="fd-component-sections"><section class="fd-demo-section"><header><p class="fd-eyebrow">Player</p><h3>Audio block</h3><p>Play the bundled recording, paste another compatible URL, or select a local audio file.</p></header><div class="fd-media-demo" data-media-demo><div class="fd-media-card"><div class="fd-media-card__art">${icon('headphones-1')}</div><div><span class="fd-badge fd-badge--success">20 sec · Spoken audio</span><h3>Foundry UI introduction</h3><p>A real, self-contained MP3 recording for testing playback and accessible media content.</p></div></div><audio controls preload="metadata" src="assets/media/demo-audio.mp3" aria-describedby="audio-sample-summary">Your browser does not support audio playback. <a href="assets/media/demo-audio.mp3">Download the MP3 file</a>.</audio><p id="audio-sample-summary" class="fd-description">English spoken-word sample · MP3 · 128 kbps · 20 seconds</p><div class="fd-media-source"><label class="fd-field"><span class="fd-label">Audio URL</span><input class="fd-input" type="url" value="assets/media/demo-audio.mp3"></label><button class="fd-button fd-button--secondary" type="button" data-media-load>Load URL</button><label class="fd-button fd-button--tertiary">${icon('upload')} Choose audio<input class="fd-visually-hidden" type="file" accept="audio/*"></label><a class="fd-button fd-button--tertiary" href="assets/media/demo-audio.mp3" download>${icon('download')} Download MP3</a></div><details class="fd-details fd-media-transcript"><summary>Read transcript ${icon('plus')}</summary><div class="fd-details__content"><p>Welcome to Foundry UI. This short audio sample demonstrates a production-ready media block. The player uses native browser controls, works without an external service, and includes a complete transcript for accessible testing. You can replace this recording with any compatible local file or audio URL in your own project.</p></div></details></div></section><section class="fd-demo-section fd-demo-section--split"><article><header><p class="fd-eyebrow">Loading</p><h3>Buffering</h3></header><div class="fd-media-state"><span class="fd-spinner"></span><strong>Preparing audio</strong><span>Playback will begin when enough media is available.</span></div></article><article><header><p class="fd-eyebrow">Unavailable</p><h3>Fallback</h3></header><div class="fd-media-state is-error">${icon('error')}<strong>Audio unavailable</strong><span>Download the transcript or try again.</span><button class="fd-button fd-button--secondary fd-button--small">View transcript</button></div></article></section></div>`, accessibility: ['Provide a complete transcript for spoken content.', 'Do not autoplay audio with sound.', 'Expose duration, playback, volume, download, and replacement controls through native semantics.', 'Keep fallback text and a direct download available when native playback is unsupported.'] },
  { group: 'Components', id: 'video', name: 'Video', description: 'A real, self-contained product walkthrough with responsive native playback, MP4 and WebM sources, poster, English captions, transcript, URL testing, local file insertion, and fallback content.', preview: `<div class="fd-component-sections"><section class="fd-demo-section"><header><p class="fd-eyebrow">Player</p><h3>Video block</h3><p>Play the bundled walkthrough, paste another compatible URL, or select a local video file.</p></header><div class="fd-media-demo" data-media-demo><div class="fd-media-card"><div class="fd-media-card__art">${icon('play')}</div><div><span class="fd-badge fd-badge--success">22 sec · Captions included</span><h3>Foundry UI product walkthrough</h3><p>An original local video demonstrating reusable components, responsive previews, and accessible delivery.</p></div></div><video controls playsinline preload="metadata" poster="assets/media/demo-video-poster.png" aria-describedby="video-sample-summary"><source src="assets/media/demo-video.mp4" type="video/mp4"><source src="assets/media/demo-video.webm" type="video/webm"><track kind="captions" src="assets/media/demo-video.vtt" srclang="en" label="English" default>Your browser does not support video playback. <a href="assets/media/demo-video.mp4">Download the MP4 file</a>.</video><p id="video-sample-summary" class="fd-description">English product walkthrough · 1280 × 720 · H.264/AAC and VP9/Opus · 22 seconds</p><div class="fd-media-source"><label class="fd-field"><span class="fd-label">Video URL</span><input class="fd-input" type="url" value="assets/media/demo-video.mp4"></label><button class="fd-button fd-button--secondary" type="button" data-media-load>Load URL</button><label class="fd-button fd-button--tertiary">${icon('upload')} Choose video<input class="fd-visually-hidden" type="file" accept="video/*"></label><a class="fd-button fd-button--tertiary" href="assets/media/demo-video.mp4" download>${icon('download')} Download MP4</a></div><details class="fd-details fd-media-transcript"><summary>Read transcript ${icon('plus')}</summary><div class="fd-details__content"><p>Welcome to Foundry UI. This short walkthrough shows how reusable components, responsive previews, theme controls, and copyable code work together. Every example is portable, accessible, and ready for desktop, tablet, and phone layouts. Use the library as a starting point, then customise its design tokens for your product.</p></div></details></div></section><section class="fd-demo-section"><header><p class="fd-eyebrow">Compatibility</p><h3>Local source fallback</h3><p>Use multiple source elements so each browser can select a supported format without an external player.</p></header><div class="fd-media-compatibility"><article>${icon('check')}<span><strong>MP4 fallback</strong><small>H.264 High, yuv420p video with AAC-LC audio</small></span></article><article>${icon('check')}<span><strong>WebM fallback</strong><small>VP9 video with Opus audio</small></span></article><article>${icon('check')}<span><strong>Native captions</strong><small>English WebVTT track included locally</small></span></article><article>${icon('check')}<span><strong>Inline mobile playback</strong><small>Native controls with playsinline enabled</small></span></article></div></section><section class="fd-demo-section fd-demo-section--split"><article><header><p class="fd-eyebrow">Loading</p><h3>Preparing video</h3></header><div class="fd-media-state"><span class="fd-spinner"></span><strong>Loading media</strong><span>The player preserves its 16:9 footprint while media becomes available.</span></div></article><article><header><p class="fd-eyebrow">Unavailable</p><h3>Fallback</h3></header><div class="fd-media-state is-error">${icon('error')}<strong>Video unavailable</strong><span>Offer a direct download and the complete transcript.</span><a class="fd-button fd-button--secondary fd-button--small" href="assets/media/demo-video.mp4" download>Download video</a></div></article></section></div>`, accessibility: ['Provide synchronised captions for speech and meaningful sound.', 'Provide a complete transcript and audio description when visual information is essential.', 'Do not autoplay video with sound; preserve native keyboard and full-screen controls.', 'Offer more than one local source format and a direct download when playback is unsupported.'] }
);

